[{"location":"#LienardWiechert","page":"Home","title":"LienardWiechert","text":"Documentation for LienardWiechert.\n\n","category":"section"},{"location":"#LienardWiechert.WorldLine","page":"Home","title":"LienardWiechert.WorldLine","text":"WorldLine{T}(data::Matrix{T})\n\nDiscrete space-time curve with times t and space coordinates x,y, and z. \n\nFields\n\ndata::Matrix{T}: A 7xN matrix holding with the columns [t, x, y, z, dx/dt, dy/dt, dz/dt]\n\nExamples\n\njulia> bar([1, 2], [1, 2])\n1\n\n\n\n\n\n","category":"type"},{"location":"#LienardWiechert.minkowski_distance_squared-Tuple{Any, Any}","page":"Home","title":"LienardWiechert.minkowski_distance_squared","text":"Calculate the Minkowski distance squared between two spacetime points, (+–-) signature.\n\n\n\n\n\n","category":"method"},{"location":"#LienardWiechert.minkowski_dot-Tuple{Any, Any}","page":"Home","title":"LienardWiechert.minkowski_dot","text":"η(r1,r2) = t1t2 - x1x2 - y1y2 - z1z2 with r1 = (t1,x1,y1,z1) and r2 = (t2,x2,y2,z2).\n\n\n\n\n\n","category":"method"},{"location":"#LienardWiechert.root_linear_interpolation-NTuple{4, Any}","page":"Home","title":"LienardWiechert.root_linear_interpolation","text":"Fit a linear function to two points (x1,t1) and (x2,t2) and return the root (t when x=0).\n\n\n\n\n\n","category":"method"}]
